-- Shared BMS. Database-level workforce authorization on privileged assignment edits.
CREATE OR REPLACE FUNCTION public.bms_update_assignment(p_tenant uuid, p_reference text, p_assignment uuid, p_data jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$ declare uid uuid:=auth.uid(); jid uuid; out jsonb; addp numeric:=coalesce(nullif(p_data->>'add_payment','')::numeric,0); begin if uid is null or not exists(select 1 from business_software_users where tenant_id=p_tenant and auth_user_id=uid and status='active' and ((jsonb_typeof(permissions)='array' and permissions ? 'manage_workforce') or ((permissions is null or permissions='[]'::jsonb) and role in ('admin','manager','owner')))) then raise exception 'not authorised'; end if; select id into jid from business_software_jobs where tenant_id=p_tenant and upper(reference)=upper(p_reference); update business_software_job_people set status=coalesce(nullif(p_data->>'status',''),status),scope=case when p_data?'scope' then nullif(p_data->>'scope','') else scope end,materials_included=case when p_data?'materials_included' then (p_data->>'materials_included')::boolean else materials_included end,agreed_cost=case when p_data?'agreed_cost' then nullif(p_data->>'agreed_cost','')::numeric else agreed_cost end,deposit_amount=case when p_data?'deposit_amount' then nullif(p_data->>'deposit_amount','')::numeric else deposit_amount end,paid_amount=case when p_data?'paid_amount' then coalesce(nullif(p_data->>'paid_amount','')::numeric,paid_amount) else paid_amount end,scheduled_at=case when p_data?'scheduled_at' then nullif(p_data->>'scheduled_at','')::timestamptz else scheduled_at end,completed_at=case when p_data?'completed_at' then nullif(p_data->>'completed_at','')::timestamptz else completed_at end where tenant_id=p_tenant and job_id=jid and id=p_assignment returning to_jsonb(business_software_job_people.*) into out; if p_data ? 'add_payment' or p_data ? 'paid_amount' then raise exception 'Payment balances may only change through idempotent payment recording'; end if; return jsonb_build_object('assignment',out); end $function$
;
